<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Api\BaseApiController; use App\Models\Coupon; use Illuminate\Http\Request;
class CouponController extends BaseApiController { public function index(){return $this->ok(Coupon::latest()->get());} public function show(Coupon $coupon){return $this->ok($coupon);} public function store(Request $r){return $this->save($r);} public function update(Request $r,Coupon $coupon){return $this->save($r,$coupon);} public function destroy(Coupon $coupon){$coupon->delete();return $this->ok();} private function save(Request $r,?Coupon $coupon=null){$d=$r->validate(['code'=>'required|string|max:100','discount_type'=>'required|in:percent,fixed','discount_value'=>'required|numeric|min:0','min_order'=>'numeric|min:0','max_discount'=>'nullable|numeric|min:0','usage_limit'=>'nullable|integer|min:1','used_count'=>'integer|min:0','is_active'=>'boolean','starts_at'=>'nullable|date','expires_at'=>'nullable|date']);if($coupon)$coupon->update($d);else $coupon=Coupon::create($d);return $this->ok($coupon,$coupon->wasRecentlyCreated?201:200);} }
